import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture } from 'three/tsl';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [imageUrl]
 * @property {any[]} [textContent]
 * @property {any} [intent]
 * @property {any} [visualSpec]
 *
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {{loadTexture(url:string):Promise<any>}} textureLoader
 * @property {{emit(event:string, payload:any):void}} emit
 * @property {{[key:string]:(target:any, params:any)=>{timeline:any, cleanup:()=>void}}} primitives
 * @property {{createText(content:string, opts?:any):any}} fontAtlas
 */

/**
 * Create a billboarded sprite with optional label text.
 *
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3 } = ctx.THREE;

  const root = new Group();

  // ------- Plane (sprite) -------
  const rect = { x: 0, y: 0, w: 512, h: 320 };
  const aspect = rect.w / rect.h; // width / height
  const geometry = new PlaneGeometry(aspect, 1, 1, 1);
  const material = new MeshBasicNodeMaterial();
  material.transparent = true;

  const plane = new Mesh(geometry, material);
  // billboard toward the active camera on each render
  plane.onBeforeRender = (renderer, scene, camera) => {
    plane.quaternion.copy(camera.quaternion);
  };
  root.add(plane);

  // Load texture asynchronously; assignment happens when ready
  let loadedTexture = null;
  ctx.textureLoader
    .loadTexture(config.imageUrl)
    .then((tex) => {
      loadedTexture = tex;
      material.colorNode = texture(tex);
      material.needsUpdate = true;
    })
    .catch(() => {
      // texture failed – keep material empty
    });

  // ------- Text label (if any) -------
  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  const textObjects = [];

  for (const item of items) {
    const opts = {
      fontSize: item.typography?.fontSize || 39,
      color: (config.visualSpec?.colors?.paper) || '#e8ecf2',
      align: 'center',
    };
    const txt = ctx.fontAtlas.createText(item.text ?? '', opts);
    // position slightly in front of the plane to avoid z‑fighting
    txt.position.set(0, 0, 0.01);
    root.add(txt);
    textObjects.push(txt);
  }

  // ------- Cleanup ----------
  root.userData.cleanup = () => {
    // dispose material and geometry
    material.dispose();
    geometry.dispose();

    // dispose loaded texture if present
    if (loadedTexture && loadedTexture.dispose) {
      loadedTexture.dispose();
    }

    // dispose any text objects (they may have internal cleanup)
    for (const txt of textObjects) {
      if (txt.userData && typeof txt.userData.cleanup === 'function') {
        txt.userData.cleanup();
      }
      if (txt.geometry) txt.geometry.dispose();
      if (txt.material) txt.material.dispose();
    }

    // kill any GSAP timelines (none expected here but defensive)
    gsap.globalTimeline.clear();
  };

  // placeholder for event handlers (none required for this node)
  root.userData.handlers = {};

  return root;
}
